"""Explain KMSAN page allocation and copy policy in beginner Korean."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1753': ('복사한 공책의 검사표를 옮기려는데 원본 검사표가 없어요. 이때 검사 도구가 어떻게 표시하는지와 실제 공책 내용이 무엇인지는 따로 생각해야 해요.', '원본 검사 정보가 없을 때의 처리와 검사 순서를 구별합니다.', '도착 검사표 있음/없음, 원본 검사표 있음/없음의 네 칸을 그리고 각 경우의 처리 방법을 적어 보세요.', ['KMSAN은 아직 값을 넣지 않은 메모리를 읽는 실수를 찾는 도구예요. 메타데이터는 실제 내용 옆에 두는 검사 정보예요. shadow는 값이 준비됐는지 나타내고 origin은 문제가 시작된 원인을 가리켜요.', 'kmsan_copy_page_meta에서 dst는 복사할 곳인 도착 페이지, src는 복사해 올 원본 페이지예요. 페이지는 메모리를 일정한 크기로 나눈 덩어리예요. 이 함수는 실제 내용에 맞춰 검사 정보를 처리해요.', '먼저 검사 도구가 꺼져 있거나 도구 자신의 처리 중이면 끝나요. 그다음 도착 페이지가 없거나 도착 검사 정보가 없으면 끝나요. 이때 원본 검사 정보가 있는지는 아직 보지 않아요.', '도착 검사 정보는 있지만 원본 페이지가 없거나 원본 검사 정보가 없으면, 도착지 한 페이지를 unpoison해요. 이 말은 검사표를 준비됨 상태로 바꾼다는 뜻이에요. 원본 데이터를 조사해서 안전함을 증명했다는 뜻은 아니에요.', '예를 들어 페이지 크기가 4096바이트라면 검사 상태를 바꾸는 범위도 4096바이트예요. 실제 도착 데이터가 9였다면 이 호출이 그 데이터를 0으로 지우는 것은 아니에요. 내용과 검사표를 구별하세요.', '호출의 마지막 false는 checked 옵션을 끈다는 뜻이에요. 원문은 이 경로에서 unchecked 방식으로 unpoison해요. 원본 정보가 없을 때 새 원본 페이지를 만드는 코드도 없어요. 조건을 위에서부터 읽고 return에서 멈춰 보세요.'], [('도착 검사표는 있지만 원본 페이지가 없어요. 이 함수는 어떻게 하나요?', ['새 원본 페이지를 만들어 내용을 채워요', '도착지 한 페이지의 검사 상태를 준비됨으로 바꿔요'], '정답은 두 번째예요. page_address(dst), PAGE_SIZE, false로 unpoison을 요청해요. 이는 검사 정보 처리이며 원본 내용이 실제로 초기화됐다는 증명은 아니에요.'), ('KMSAN 자신의 처리 중에도 원본이 없는 경우의 검사표 변경을 하나요?', ['아니요. 첫 번째 조건에서 함수를 끝내요', '네. 원본이 없으면 앞 조건을 무시해요'], '정답은 첫 번째예요. kmsan_in_runtime 검사가 원본 검사보다 먼저 있어요. return을 만나면 아래 코드는 실행하지 않아요.')]), 'os1754': ('빈 공책을 받는 일과 공책에 준비 완료 표시를 붙이는 일은 달라요. 여기서는 메모리를 받은 뒤 검사표를 어떻게 바꾸는지 살펴봐요.', '페이지 묶음의 크기를 계산하고 실제 데이터와 검사 정보의 초기화를 구별합니다.', 'order가 0, 1, 2일 때 페이지 수를 1, 2, 4로 쓰고 페이지 크기 4096을 각각 곱해 보세요.', ['kmsan_alloc_page는 메모리 페이지를 할당할 때 검사 상태를 반영하는 함수예요. 할당은 사용할 메모리 자리를 받는 일이에요. 이 함수 안의 memset은 검사 정보에 값을 채우는 작업이에요.', 'flags는 요청 조건을 모아 둔 표시예요. 그 안에 __GFP_ZERO가 있으면 0으로 채워진 메모리를 요청한 경우예요. 또는 KMSAN이 꺼져 있어도 이 함수의 initialized 조건은 참이 돼요.', 'initialized가 참이면 shadow와 origin을 각각 0으로 채우고 끝나요. shadow의 0은 준비되지 않은 비트가 없다는 표시이고 origin의 0은 원인 번호를 비우는 표시예요. 검사 도구가 꺼진 경우의 정책을 실제 데이터 검사 결과로 받아들이면 안 돼요.', 'order는 페이지 개수 자체가 아니에요. pages = 1 << order는 여기서 1을 두 배씩 order번 늘리는 계산이에요. order 0이면 1페이지, 1이면 2페이지, 2이면 4페이지예요.', '각 검사 정보에 채우는 길이는 PAGE_SIZE 곱하기 pages예요. 페이지가 4096바이트이고 order가 1이면 shadow 8192바이트와 origin 8192바이트를 각각 0으로 채워요. 두 표의 길이를 하나로 혼동하지 마세요.', '실제 데이터 페이지를 0으로 채우는 작업은 이 두 memset의 대상이 아니에요. 이 함수는 할당 과정의 조건을 검사표에 반영해요. page가 NULL이면 먼저 돌아가며, 정상 경로에서는 연결된 검사 페이지가 준비되어 있다는 조건으로 코드를 읽어요.'], [('order가 1이고 페이지 하나가 4096바이트라면 shadow를 얼마나 0으로 채우나요?', ['4096바이트예요', '8192바이트예요'], '정답은 두 번째예요. 1 << 1은 2이므로 4096 × 2 = 8192예요. origin에도 같은 길이를 따로 적용해요.'), ('이 함수의 두 memset이 직접 0으로 채우는 것은 무엇인가요?', ['shadow와 origin이라는 검사 정보예요', '사용자가 사용할 실제 데이터 페이지예요'], '정답은 첫 번째예요. 대상 주소를 얻을 때 shadow와 origin을 사용해요. 데이터에 값을 쓰는 일과 그 상태를 검사표에 적는 일은 구별해야 해요.')]), 'os1755': ('점검 담당자가 자기 도구를 점검하다가 다시 점검을 시작하면 끝없이 반복될 수 있어요. 그래서 멈춤 조건을 두지만, 그보다 먼저 처리해야 할 표시도 있어요.', '초기화 분기와 runtime 검사 순서가 결과를 바꾸는 이유를 이해합니다.', 'KMSAN 켜짐과 정상 페이지를 가정하고 runtime 안에서 ZERO 있음/없음의 화살표를 각각 그리세요.', ['runtime은 여기서 KMSAN 도구 자신의 일을 처리하는 중인 상태를 말해요. 도구가 자기 일을 계속 새 검사 대상으로 삼으면 같은 처리가 거듭 이어질 수 있어요. 이를 피하려고 중간에 돌아가는 조건을 둬요.', 'kmsan_alloc_page는 먼저 initialized를 살펴봐요. __GFP_ZERO가 있거나 KMSAN이 꺼져 있으면 이 조건은 참이에요. 정상 페이지라면 shadow와 origin을 0으로 채우고 그 호출을 끝내요.', '그다음에야 kmsan_in_runtime을 검사해요. 따라서 KMSAN이 켜져 있고 도구 자신의 처리 중이어도 ZERO 요청이면 검사 정보의 0 채우기가 먼저 실행돼요. runtime이라는 단어만 보고 모든 처리를 생략한다고 읽으면 순서를 놓쳐요.', '반대로 KMSAN이 켜져 있고 ZERO 요청도 아닌데 runtime 안이라면, initialized 분기를 지나 다음 조건에서 끝나요. 아래에 있는 shadow의 미준비 표시와 새 원인 기록 저장은 실행하지 않아요.', '예를 들어 기존 shadow 바이트가 31이라고 해 봐요. 위 조건에서 ZERO가 없으면 이 함수는 그 값을 그대로 두고 돌아가요. ZERO가 있으면 초기화 분기에서 0으로 바꿔요. 이는 분기 비교용 예시이며 31이 실제 데이터 값이라는 뜻은 아니에요.', '원문 주석은 도구 내부에서 할당한 zero 페이지도 초기화된 것으로 표시해야 한다고 설명해요. 그러므로 runtime 검사를 함수 맨 앞으로 옮기면 같은 뜻이 유지되지 않아요. 조건의 내용과 함께 배치 순서도 읽어야 해요.'], [('정상 페이지이고 KMSAN이 켜져 있어요. runtime 안에서 ZERO 요청을 받으면 검사 정보의 0 채우기를 건너뛰나요?', ['네. runtime이면 무조건 모든 작업을 건너뛰어요', '아니요. 초기화 분기가 runtime 검사보다 앞에 있어요'], '정답은 두 번째예요. initialized 분기에서 두 검사표를 0으로 채우고 돌아가요. 뒤의 runtime 검사까지 도달하지 않아요.'), ('같은 조건에서 ZERO 요청이 없으면 새 원인 기록을 저장하나요?', ['아니요. runtime 검사에서 끝나요', '네. 모든 호출에서 반드시 새로 저장해요'], '정답은 첫 번째예요. initialized가 거짓이면 runtime 조건으로 넘어가고, 그 조건이 참이므로 저장 코드에 도달하기 전에 돌아가요.')]), 'os1756': ('여러 상자가 한 번에 같은 장소에서 도착했다면 상자마다 서로 다른 출발지를 만들 필요는 없어요. 같은 출발 기록 번호를 여러 칸에 적을 수 있어요.', '미준비 상태 표시와 여러 원인 칸이 같은 기록 번호를 공유하는 이유를 이해합니다.', '페이지 4096바이트 두 개, 원인 번호 크기 4바이트를 가정하고 원인 칸 수 8192 ÷ 4를 계산하세요.', ['이번 경로는 정상 페이지와 검사 정보가 있고, KMSAN이 켜져 있으며, ZERO 요청이 아니고, 도구 자신의 처리 중도 아닐 때예요. 앞의 반환 조건을 모두 지난 뒤의 작업을 읽어요.', '먼저 shadow 전체를 -1로 채워요. memset은 바이트마다 채우므로 각 바이트는 FF가 돼요. FF는 16진수 표기이며 이진수로는 11111111이에요. 검사에서는 해당 비트들이 아직 준비되지 않았다는 표시예요. 실제 데이터에 FF를 쓰는 작업은 아니에요.', '이어서 enter_runtime으로 도구 처리에 들어가고, kmsan_save_stack_with_flags로 지금까지 어떤 함수들을 거쳐 왔는지 기록을 저장해요. 반환된 handle은 그 기록을 가리키는 번호예요. 그다음 leave_runtime으로 나와요.', '마지막 반복문은 origin의 각 칸에 같은 handle을 넣어요. 한 번의 할당에서 생긴 메모리 묶음이므로 여러 칸이 같은 할당 원인을 가리켜요. 바이트마다 별도의 호출 기록을 저장하는 방식이 아니에요.', '예를 들어 페이지 크기 4096바이트, order 1, handle 크기 4바이트라면 원인 칸은 4096 × 2 ÷ 4 = 2048개예요. 저장 결과가 77이라면 2048개 칸에 모두 77을 적어요. 77은 이해를 돕기 위한 예시 번호예요.', '원문은 주소가 페이지 경계에 맞고 페이지들이 연속으로 이어져 있다고 설명해요. 그래서 한 시작 주소에서 칸 번호를 늘리며 채울 수 있어요. 서로 떨어진 임의의 메모리에 그대로 적용할 수는 없어요. 저장이 성공해 항상 77 같은 유효 번호를 얻는다는 보장도 이 반복문만으로 생기지는 않아요.'], [('한 번의 일반 할당에서 원인 기록 번호 77을 얻었다면 origin의 여러 칸에는 무엇을 넣나요?', ['각 바이트마다 새 기록을 저장해 서로 다른 번호를 넣어요', '저장한 같은 번호 77을 여러 칸에 넣어요'], '정답은 두 번째예요. 저장 함수는 반복문 앞에서 호출하고, 반복문 안에서는 같은 handle을 넣어요. 여러 부분이 같은 할당 원인을 공유해요.'), ('이 함수가 origin 칸을 순서대로 채울 수 있다고 설명하는 조건은 무엇인가요?', ['주소가 페이지 경계에 맞고 페이지들이 연속으로 이어져 있어요', '페이지가 어디에 흩어져 있어도 시작 주소 하나면 충분해요'], '정답은 첫 번째예요. 원문 주석에 page-aligned와 contiguous가 있어요. 임의로 흩어진 페이지라면 이처럼 한 시작 주소에서 계속 나아갈 수 없어요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_434.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
